// ==UserScript==
// @name         Global Font Override (MyFont)
// @namespace    http://tampermonkey.net/
// @version      2.1
// @description  Apply MyFont to all websites on Safari iOS, including CSP-locked sites like X. Energy-tuned.
// @author       asf383
// @match        *://*/*
// @run-at       document-start
// @grant        GM_addStyle
// @updateURL    https://raw.githubusercontent.com/asf383/myfont/main/myfont.meta.js
// @downloadURL  https://raw.githubusercontent.com/asf383/myfont/main/myfont.user.js
// ==/UserScript==

(function () {
    'use strict';

    // ===== Quick exit on CSP-locked domains ============================
    //const cspLockedDomains = [
    //    'facebook.com', 'fb.com', 'messenger.com',
    //    'discord.com', 'discordapp.com',
    //    'twitter.com', 'x.com',
    //];
        const cspLockedDomains = [
     ];
    const currentHost = window.location.hostname;
    if (cspLockedDomains.some(d => currentHost === d || currentHost.endsWith('.' + d))) {
        return;
    }

    // ===== Configuration ==============================================
    const FONT_URL = 'data:font/woff2;base64,';
    const SYSTEM_STACK = "-apple-system, BlinkMacSystemFont, 'Helvetica Neue', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif";

    // MyFont is only used for these characters: Latin, common punctuation
    // and currency, plus Chinese, Japanese and Korean. Anything else (icon
    // glyphs in the Private Use Area, emoji, Thai, Arabic, ...) falls
    // through to the site's own fonts, then the system fonts.
    const MYFONT_RANGE = [
        // Latin
        'U+0000-02FF',   // Basic Latin, Latin-1, Latin Extended-A/B, IPA, modifiers
        'U+1E00-1EFF',   // Latin Extended Additional (Vietnamese etc.)
        'U+2000-206F',   // General punctuation
        'U+20A0-20CF',   // Currency symbols
        'U+2C60-2C7F', 'U+A720-A7FF', // Latin Extended-C/D
        // CJK
        'U+2E80-2FDF',   // CJK radicals, Kangxi radicals
        'U+3000-30FF',   // CJK punctuation, Hiragana, Katakana
        'U+3100-31FF',   // Bopomofo, Hangul compat jamo, CJK strokes
        'U+3200-33FF',   // Enclosed CJK, CJK compatibility
        'U+3400-4DBF',   // CJK Extension A
        'U+4E00-9FFF',   // CJK Unified Ideographs
        'U+AC00-D7AF',   // Hangul syllables
        'U+F900-FAFF',   // CJK compatibility ideographs
        'U+FE30-FE4F',   // CJK compatibility forms
        'U+FF00-FFEF',   // Halfwidth and fullwidth forms
        'U+20000-2FA1F', // CJK Extensions B and later
    ].join(', ');
    const STYLE_ID = 'myfont-override';
    const SHADOW_STYLE_MARK = 'data-myfont-shadow';

    // After this many ms of no new shadow roots, disconnect observers.
    const IDLE_DISCONNECT_MS = 30000;

    // Sites that declare these font-family names will be remapped to MyFont
    // by shadowing their @font-face declarations.
    const SHADOWED_FONTS = [
        'GH Guardian Headline',
        'GuardianTextEgyptian',
        'GuardianTextSans',
        'GT Guardian Titlepiece',
    ];

    // ===== Font registration via the FontFace API =====================
    // Sites like X/Twitter send a Content-Security-Policy whose font-src
    // does not allow data: URLs, so an @font-face with a data: URL is
    // refused there. A FontFace built from raw bytes involves no URL
    // fetch, so font-src does not apply. It also means the 5.6 MB font
    // is decoded once instead of being copied into the CSS five times.
    function registerFontsViaAPI() {
        if (typeof FontFace !== 'function' || !document.fonts) return false;
        try {
            const b64 = FONT_URL.slice(FONT_URL.indexOf(',') + 1);
            const bin = atob(b64);
            const bytes = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);

            const names = ['MyFont'].concat(SHADOWED_FONTS);
            for (let i = 0; i < names.length; i++) {
                const face = new FontFace(names[i], bytes, {
                    weight: '100 900',
                    display: 'swap',
                    unicodeRange: MYFONT_RANGE,
                });
                document.fonts.add(face);
                if (face.status === 'error') throw new Error('font parse failed: ' + names[i]);
            }
            return true;
        } catch (e) {
            console.warn('[MyFont] FontFace registration failed, falling back to @font-face', e);
            return false;
        }
    }
    const FONTS_VIA_API = registerFontsViaAPI();

    // ===== Site font discovery ========================================
    // Because our rule replaces the site's font-family, a character MyFont
    // doesn't handle would normally skip the site's fonts (including its
    // icon font) and land on the system font. To avoid that, we read the
    // font families the site has loaded from document.fonts and put them
    // right after MyFont in our stack. An icon glyph then falls back to
    // the site's icon font, exactly as it would without this script.
    const OWN_FAMILIES = new Set(['myfont'].concat(
        SHADOWED_FONTS.map(f => f.toLowerCase())));
    let siteFamilies = [];

    function collectSiteFamilies() {
        const found = [];
        const seen = new Set();
        try {
            document.fonts.forEach((face) => {
                const fam = String(face.family).replace(/^["']|["']$/g, '').trim();
                const key = fam.toLowerCase();
                if (!fam || OWN_FAMILIES.has(key) || seen.has(key)) return;
                seen.add(key);
                found.push(fam);
            });
        } catch (_) { /* document.fonts not iterable: keep old list */ }
        return found;
    }

    function fontStack() {
        const site = siteFamilies.map(f => '"' + f.replace(/["\\]/g, '\\$&') + '"');
        return ["'MyFont'"].concat(site, [SYSTEM_STACK]).join(', ');
    }

    // ===== CSS construction ===========================================
    function buildCSS() {
        let css = '';
        if (!FONTS_VIA_API) {
            css += `
                @font-face {
                    font-family: 'MyFont';
                    src: url('${FONT_URL}') format('woff2');
                    unicode-range: ${MYFONT_RANGE};
                    font-display: swap;
                }
            `;
            for (let i = 0; i < SHADOWED_FONTS.length; i++) {
                css += `
                    @font-face {
                        font-family: '${SHADOWED_FONTS[i]}';
                        src: url('${FONT_URL}') format('woff2');
                        font-weight: 100 900;
                        unicode-range: ${MYFONT_RANGE};
                        font-display: swap;
                    }
                `;
            }
        }
        // Elements we must never touch, so the site's own font-family
        // (icon fonts etc.) stays in effect.
        const EXCLUDE = [
            '[class*="icon"]', '[class*="Icon"]',
            '[class*="sprite"]', '[class*="Sprite"]',
            '.fa', '[class^="fa-"]', '[class*=" fa-"]',
            '.fas', '.far', '.fab', '.fal', '.fad',
            '.glyphicon', '.bi',
            '[class*="material-icons"]', '[class*="material-symbols"]',
            'svg', 'svg *',
            '[role="img"]',
            '[class*="PlayerControls"]', '[class*="player-controls"]',
            '[class*="VideoControls"]', '[class*="video-controls"]',
            '[class*="watch-video"]', '[class*="nf-player"]',
            '.watch-video--player-view', '.sizing-wrapper',
            '[class*="Emoji"]:not([class*="Text"])',
            '[class*="emoji"]:not([class*="text"])',
            '[aria-hidden="true"]',
            '[data-visualcompletion="ignore"]',
            '[data-visualcompletion="css-img"]',
        ].join(', ');

        css += `
            html body,
            html body *:not(${EXCLUDE}) {
                font-family: ${fontStack()} !important;
            }
        `;
        return css;
    }

    // Build the CSS string exactly once and freeze it.
    siteFamilies = collectSiteFamilies();
    let CSS_TEXT = buildCSS();
    const shadowStyleEls = new Set();

    // Try to construct a single shared CSSStyleSheet. If supported, every
    // shadow root will reference this same object instead of holding its
    // own copy of the CSS text in a <style> element. Big memory win on
    // pages with many custom elements.
    let sharedSheet = null;
    let canUseConstructable = false;
    try {
        if (typeof CSSStyleSheet === 'function' &&
            typeof CSSStyleSheet.prototype.replaceSync === 'function' &&
            'adoptedStyleSheets' in Document.prototype) {
            sharedSheet = new CSSStyleSheet();
            sharedSheet.replaceSync(CSS_TEXT);
            canUseConstructable = true;
        }
    } catch (_) {
        // Older Safari throws here. Falls back to <style>-per-root.
        sharedSheet = null;
        canUseConstructable = false;
    }

    // ===== Idle scheduler =============================================
    const scheduleIdle = (typeof window.requestIdleCallback === 'function')
        ? (cb) => window.requestIdleCallback(cb, { timeout: 500 })
        : (cb) => setTimeout(cb, 50);

    // ===== Main-document style injection ==============================
    function injectMainStyle() {
        // If our <style> is already last in <head>, nothing to do.
        const head = document.head || document.documentElement;
        const existing = document.getElementById(STYLE_ID);
        if (existing && existing.parentNode === head && existing === head.lastElementChild) {
            return;
        }
        if (existing) {
            // Just move it to the end — cheap pointer swap, no string rebuild.
            head.appendChild(existing);
            return;
        }
        const style = document.createElement('style');
        style.id = STYLE_ID;
        style.textContent = CSS_TEXT;
        head.appendChild(style);
    }

    // Also adopt the shared stylesheet on the main document, so the
    // main-document CSS comes through the constructable path too when
    // supported. The <style> in <head> still exists as a belt-and-
    // suspenders fallback and to win source-order ties.
    if (canUseConstructable) {
        try {
            document.adoptedStyleSheets = [...document.adoptedStyleSheets, sharedSheet];
        } catch (_) { /* ignore */ }
    }
    injectMainStyle();

    // ===== Keep the fallback list in step with the site's fonts =======
    function refreshSiteFonts() {
        const next = collectSiteFamilies();
        if (next.length === siteFamilies.length &&
            next.every((f, i) => f === siteFamilies[i])) return;
        siteFamilies = next;
        CSS_TEXT = buildCSS();
        const el = document.getElementById(STYLE_ID);
        if (el) el.textContent = CSS_TEXT;
        if (sharedSheet) {
            try { sharedSheet.replaceSync(CSS_TEXT); } catch (_) { /* ignore */ }
        }
        shadowStyleEls.forEach((s) => {
            if (s.isConnected) s.textContent = CSS_TEXT;
            else shadowStyleEls.delete(s);
        });
    }

    let fontRefreshPending = false;
    function scheduleFontRefresh() {
        if (fontRefreshPending) return;
        fontRefreshPending = true;
        scheduleIdle(() => {
            fontRefreshPending = false;
            refreshSiteFonts();
        });
    }

    if (document.fonts && document.fonts.addEventListener) {
        document.fonts.addEventListener('loading', scheduleFontRefresh);
        document.fonts.addEventListener('loadingdone', scheduleFontRefresh);
    }
    document.addEventListener('DOMContentLoaded', scheduleFontRefresh, { once: true });
    window.addEventListener('load', () => {
        scheduleFontRefresh();
        setTimeout(scheduleFontRefresh, 3000);
    }, { once: true });

    // ===== Head observer (throttled, self-disconnecting) ==============
    let headObserver = null;
    let headLastFire = 0;
    let headPending = false;

    function startHeadObserver() {
        if (!document.head || headObserver) return;
        headObserver = new MutationObserver((mutations) => {
            // Only care about *other* <style>/<link> additions.
            let relevant = false;
            for (let m = 0; m < mutations.length; m++) {
                const added = mutations[m].addedNodes;
                for (let i = 0; i < added.length; i++) {
                    const n = added[i];
                    if (n.nodeType === 1 && n.id !== STYLE_ID &&
                        (n.tagName === 'STYLE' || n.tagName === 'LINK')) {
                        relevant = true;
                        break;
                    }
                }
                if (relevant) break;
            }
            if (!relevant || headPending) return;
            // Hard throttle: at most one reassertion per second.
            const now = Date.now();
            if (now - headLastFire < 1000) return;
            headLastFire = now;
            headPending = true;
            scheduleIdle(() => {
                headPending = false;
                injectMainStyle();
                refreshSiteFonts();
            });
        });
        headObserver.observe(document.head, { childList: true });
    }

    function stopHeadObserver() {
        if (headObserver) {
            headObserver.disconnect();
            headObserver = null;
        }
    }

    if (document.head) {
        startHeadObserver();
    } else {
        document.addEventListener('DOMContentLoaded', startHeadObserver, { once: true });
    }

    // ===== Shadow-DOM injection =======================================
    // Only custom elements can host shadow roots, and custom-element tag
    // names always contain a hyphen. We exploit that to skip the vast
    // majority of nodes without ever touching them.

    const seenShadowRoots = new WeakSet();

    function attachToShadowRoot(root) {
        if (!root || seenShadowRoots.has(root)) return;
        seenShadowRoots.add(root);
        try {
            if (canUseConstructable && 'adoptedStyleSheets' in root) {
                // Append, don't replace, to avoid stomping on the
                // component's own styles.
                root.adoptedStyleSheets = [...root.adoptedStyleSheets, sharedSheet];
                return;
            }
            // Fallback: <style>-per-root.
            if (root.querySelector && root.querySelector(`style[${SHADOW_STYLE_MARK}]`)) return;
            const style = document.createElement('style');
            style.setAttribute(SHADOW_STYLE_MARK, '');
            style.textContent = CSS_TEXT;
            root.appendChild(style);
            shadowStyleEls.add(style);
        } catch (_) {
            // Closed root or detached node — silently skip.
        }
    }

    // Scan a subtree for shadow roots, restricted to elements that could
    // plausibly have one (tag name contains a hyphen). SVG subtrees can
    // never contain custom elements, so we skip them entirely.
    function scanSubtreeForShadowRoots(root) {
        if (!root || root.nodeType !== 1) return 0;
        if (root.tagName === 'SVG' || root.tagName === 'svg') return 0;
        let found = 0;

        // The root node itself
        if (root.localName && root.localName.indexOf('-') !== -1 && root.shadowRoot) {
            if (!seenShadowRoots.has(root.shadowRoot)) {
                attachToShadowRoot(root.shadowRoot);
                found++;
            }
        }

        // Descendants — use getElementsByTagName for a live, cheap iteration
        if (!root.getElementsByTagName) return found;
        const all = root.getElementsByTagName('*');
        for (let i = 0; i < all.length; i++) {
            const el = all[i];
            // localName comparison is the fastest custom-element filter.
            const ln = el.localName;
            if (!ln || ln.indexOf('-') === -1) continue;
            const sr = el.shadowRoot;
            if (sr && !seenShadowRoots.has(sr)) {
                attachToShadowRoot(sr);
                found++;
            }
        }
        return found;
    }

    // ===== Shadow observer with idle back-off =========================
    let shadowObserver = null;
    let shadowQueue = [];
    let shadowPending = false;
    let lastNewRootAt = Date.now();
    let idleCheckTimer = null;

    function flushShadowQueue() {
        shadowPending = false;
        const queue = shadowQueue;
        shadowQueue = [];
        let foundAny = 0;
        for (let i = 0; i < queue.length; i++) {
            foundAny += scanSubtreeForShadowRoots(queue[i]);
        }
        if (foundAny > 0) lastNewRootAt = Date.now();
    }

    function startShadowObserver() {
        if (shadowObserver || !document.body) return;
        shadowObserver = new MutationObserver((mutations) => {
            for (let m = 0; m < mutations.length; m++) {
                const added = mutations[m].addedNodes;
                for (let i = 0; i < added.length; i++) {
                    const n = added[i];
                    // Only consider element nodes that could host or
                    // contain a custom element. Plain text, comments,
                    // and SVG subtrees are skipped at the source.
                    if (n.nodeType !== 1) continue;
                    if (n.tagName === 'SVG' || n.tagName === 'svg') continue;
                    shadowQueue.push(n);
                }
            }
            if (shadowQueue.length === 0 || shadowPending) return;
            shadowPending = true;
            scheduleIdle(flushShadowQueue);
        });
        shadowObserver.observe(document.body, { childList: true, subtree: true });
    }

    function stopShadowObserver() {
        if (shadowObserver) {
            shadowObserver.disconnect();
            shadowObserver = null;
        }
        if (idleCheckTimer) {
            clearInterval(idleCheckTimer);
            idleCheckTimer = null;
        }
    }

    // Periodically check whether we've gone IDLE_DISCONNECT_MS without
    // finding any new shadow root. If so, tear down BOTH observers and
    // stop spending energy on this page. Check infrequently (every 5s)
    // so the check itself is cheap.
    function startIdleWatchdog() {
        if (idleCheckTimer) return;
        idleCheckTimer = setInterval(() => {
            if (Date.now() - lastNewRootAt > IDLE_DISCONNECT_MS) {
                stopShadowObserver();
                stopHeadObserver();
            }
        }, 5000);
    }

    // ===== Bootstrap shadow watching ==================================
    // Detect at startup whether the page even uses custom elements. If
    // not (most non-app sites), don't bother attaching a body-wide
    // subtree observer at all — the head observer is enough to keep our
    // font in place.

    function bootstrapShadow() {
        if (!document.body) return;
        const initialFound = scanSubtreeForShadowRoots(document.body);
        if (initialFound > 0) {
            lastNewRootAt = Date.now();
            startShadowObserver();
            startIdleWatchdog();
            return;
        }
        // No custom elements at startup. We still want to handle SPAs
        // that mount their first custom element after initial render
        // (e.g. lazy-loaded shreddit on Reddit navigation). Give them
        // 10 seconds. If a custom element shows up in that window, fully
        // start the observer. Otherwise, give up and let the page run
        // observer-free.
        let lightweightObserver = null;
        const giveUpTimer = setTimeout(() => {
            if (lightweightObserver) {
                lightweightObserver.disconnect();
                lightweightObserver = null;
            }
        }, 10000);
        lightweightObserver = new MutationObserver((mutations) => {
            // Cheap scan: look only at directly added nodes for a
            // hyphenated localName.
            for (let m = 0; m < mutations.length; m++) {
                const added = mutations[m].addedNodes;
                for (let i = 0; i < added.length; i++) {
                    const n = added[i];
                    if (n.nodeType !== 1) continue;
                    if (n.localName && n.localName.indexOf('-') !== -1) {
                        // Custom element appeared — promote to full mode.
                        clearTimeout(giveUpTimer);
                        lightweightObserver.disconnect();
                        lightweightObserver = null;
                        // Scan the node we just saw, then start the
                        // real observer to catch everything from here on.
                        scanSubtreeForShadowRoots(n);
                        lastNewRootAt = Date.now();
                        startShadowObserver();
                        startIdleWatchdog();
                        return;
                    }
                }
            }
        });
        lightweightObserver.observe(document.body, { childList: true, subtree: true });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', bootstrapShadow, { once: true });
    } else {
        bootstrapShadow();
    }

    // ===== Visibility-aware pausing ===================================
    // When the tab is hidden, disconnect everything to save energy.
    // When it becomes visible again, do a one-shot scan to catch up.
    document.addEventListener('visibilitychange', () => {
        if (document.hidden) {
            stopShadowObserver();
            stopHeadObserver();
        } else {
            // Page came back. Reassert main style and resume watchers
            // if the page seems active. Don't restart if we already
            // gave up due to long idle.
            injectMainStyle();
            if (Date.now() - lastNewRootAt <= IDLE_DISCONNECT_MS) {
                startHeadObserver();
                if (document.body) {
                    scanSubtreeForShadowRoots(document.body);
                    startShadowObserver();
                    startIdleWatchdog();
                }
            }
        }
    });

})();
